contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public {
        require(amount > 0);
        c.mintToken(address(this), amount); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        c.transfer(address(this), amount); if (__ESBMC_reverted()) return;
        uint256 balAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(balAfter == balBefore && supplyAfter == supplyBefore);
    }
    receive() external payable {}
}

